// === Tab: Particles ===
class Particle {
	constructor(x, y, phi) {
		this.pos = {
			x,
			y
		};
		this.angle = phi*2e10;
		this.val = 1;
	}

	update(index) {
		this.pos.x += cos(this.angle)*2;
		this.pos.y += sin(this.angle)*2;

		let nx = 1.5 * scaleFunction(this.pos.x);
		let ny = 1.0 * scaleFunction(this.pos.y);

		let n = {
			x: nx,
			y: ny
		};

		let nval = (noise(n.x + perlinSeedX, n.y - perlinSeedY) + 0.045 * (index - numSets / 2)) % 5;

		this.angle += 5 * (nval * 2 - 1);
		this.val = nval;
	}

	display(index) {
		if (this.val > bottomEnd && this.val < topEnd) {
			point(this.pos.x, this.pos.y);
		}
	}
}

function scaleFunction(n) {
	return (size - n / size) * 2 - 1;
}



