let size = 600;
let numParticles = 20000;
let numSets = 5;
let particle_sets = [];
let hu = 0;
let perlinSeedX;
let perlinSeedY;
let lapse = 0;    // mouse timer

function setup() {
	perlinSeedX = round(random() * size);
	perlinSeedY = round(random() * size);
	pixelDensity(6);
	createCanvas(size, size);
	noFill();
	//background('#E9F3E2');
	background('#191919');
	// colorMode(HSB, 255);
  hu = random(255);
	//stroke(0,15);
	stroke(255, 5);
	strokeWeight(0.5);
	noFill();
	smooth();
	for (var j = 0; j < numSets; j++) {
		let particlesArray = [];

		for (var i = 0; i < numParticles; i++) {
			particlesArray.push(
				new Particle(
					randomGaussian(size / 2, 110),
					randomGaussian(size / 2, 110),
					random() * 2 * PI
				)
			);
		}
		particle_sets.push(particlesArray);
	}
}

function draw() {
	particle_sets.forEach(function(particles, index) {

		particles.forEach(function(particle) {
			particle.update(index); 
			particle.display(index); 
		});

	});

}

